const domains = ($('Call Module API - Prepare').item.json.next || {}).clay_domains || [];
const runId = $('Call Module API - Prepare').item.json.run_id;
return domains.map(domain => ({ json: { domain, run_id: runId } }));

const runId = $('Call Module API - Prepare').item.json.run_id;
const staticData = $getWorkflowStaticData('global');
const stored = (staticData.clayResults && staticData.clayResults[runId]) || {};
const domainsSent = (($('Call Module API - Prepare').item.json.next || {}).clay_domains) || [];
const clay_results = {};
for (const domain of domainsSent) {
  clay_results[domain] = stored[domain] || null;
}
if (staticData.clayResults) delete staticData.clayResults[runId];
return [{ json: { run_id: runId, clay_results, clay_domains_sent: domainsSent.length, clay_domains_returned: Object.keys(stored).length } }];

const prepare = $('Call Module API - Prepare').item.json;
const finalize = $json;

let clayDomainsSent = 0;
let clayDomainsReturned = 0;
try {
  const clayNode = $('Assemble Clay Results').item.json;
  clayDomainsSent = clayNode.clay_domains_sent;
  clayDomainsReturned = clayNode.clay_domains_returned;
} catch (e) {
  // 'Assemble Clay Results' did not execute on this run -- the no-clay branch was taken instead.
}

const receipts = [].concat(prepare.receipts || [], finalize.receipts || []);

const summary = {
  run_id: finalize.run_id || prepare.run_id,
  lane: finalize.lane || prepare.lane,
  input_rows: (prepare.summary || {}).input_rows ?? null,
  output_rows: (prepare.summary || {}).output_rows ?? null,
  hubspot_matches: (prepare.summary || {}).hubspot_matches ?? null,
  llm_calls: (prepare.summary || {}).llm_calls ?? null,
  clay_domains_sent: clayDomainsSent,
  clay_domains_returned: clayDomainsReturned,
  contacts_upserted: (finalize.summary || {}).contacts_upserted ?? null,
  verified_contact_pct: (finalize.summary || {}).verified_contact_pct ?? null,
  verified_company_pct: (finalize.summary || {}).verified_company_pct ?? null,
  receipts
};

const fileContent = Buffer.from(JSON.stringify(summary, null, 2), 'utf8').toString('base64');

return [{
  json: summary,
  binary: {
    data: {
      data: fileContent,
      mimeType: 'application/json',
      fileName: `${summary.run_id}.json`
    }
  }
}];

const body = $json.body || {};
const runId = body.run_id;
const domain = body.domain;
const staticData = $getWorkflowStaticData('global');
if (!staticData.clayResults) staticData.clayResults = {};
if (runId && domain) {
  if (!staticData.clayResults[runId]) staticData.clayResults[runId] = {};
  staticData.clayResults[runId][domain] = {
    industry: body.industry ?? null,
    employee_count: body.employee_count ?? null,
    country: body.country ?? null,
    source: 'clay',
    run_url: body.run_url ?? null
  };
}
return [{ json: { stored: Boolean(runId && domain), run_id: runId, domain } }];
